import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def f(inp):
    g=[r[:] for r in inp]; H,W=len(g),len(g[0])
    segs=[]
    for r in range(H):
        cells=[c for c,x in enumerate(inp[r]) if x!=0]
        if cells: segs.append((r,min(cells),max(cells),inp[r][min(cells)]))
    # order: topmost first
    segs.sort(key=lambda s:s[0])
    out=[r[:] for r in inp]
    # find second colored row below top segment
    top=segs[0]; next_seg=None
    for r,c0,c1,col in segs:
        if r>top[0]: next_seg=(r,c0,c1,col); break
    if next_seg is None: return out
    # columns overlapping both
    cols=set(range(top[1],top[2]+1))&set(range(next_seg[1],next_seg[2]+1))
    for c in cols:
        for r in range(top[0]+1,next_seg[0]):
            if out[r][c]==0: out[r][c]=4
    return out

